1	import 'dart:convert';
2	import 'dart:io';
3	import 'dart:math' as math;
4	
5	import 'package:latlong2/latlong.dart';
6	import 'package:sifli_companion/app/app_keys.dart';
7	
8	/// 路网吸附与两点之间沿道路补点（BRouter + OSRM，用法对齐 gpx.studio）。
9	class RoadRouter {
10	  RoadRouter._();
11	  static final RoadRouter instance = RoadRouter._();
12	
13	  static const snapMaxMeters = 200.0;
14	
15	  static const _ua = '${AppKeys.appName} (${AppKeys.androidPackage})';
16	
17	  /// 把点击吸到最近道路。太远则抛 [RoadRouterException]。
18	  Future<LatLng> snap(LatLng tap) async {
19	    final uri = Uri.https(
20	      'router.project-osrm.org',
21	      '/nearest/v1/driving/${tap.longitude},${tap.latitude}',
22	      {'number': '1'},
23	    );
24	    final json = await _getJson(uri);
25	    final snapped = parseOsrmNearest(json, tap);
26	    if (snapped == null) {
27	      throw const RoadRouterException('no road');
28	    }
29	    return snapped;
30	  }
31	
32	  /// 两点之间沿路网的折线（含起终点）。骑行剖面优先 BRouter。
33	  Future<List<LatLng>> route(LatLng from, LatLng to) async {
34	    try {
35	      final pts = parseBrouterGeoJson(await _getJson(_brouterUri(from, to)));
36	      if (pts.length >= 2) return pts;
37	    } catch (_) {}
38	    final pts = parseOsrmRoute(
39	      await _getJson(_osrmRouteUri(from, to)),
40	    );
41	    if (pts.length < 2) {
42	      throw const RoadRouterException('no route');
43	    }
44	    return pts;
45	  }
46	
47	  /// 途经点串成完整路网折线。
48	  Future<List<LatLng>> routeAnchors(List<LatLng> anchors) async {
49	    if (anchors.length < 2) return List<LatLng>.from(anchors);
50	    final out = <LatLng>[anchors.first];
51	    for (var i = 1; i < anchors.length; i++) {
52	      final leg = await route(anchors[i - 1], anchors[i]);
53	      if (leg.length >= 2) {
54	        out.addAll(leg.skip(1));
55	      } else {
56	        out.add(anchors[i]);
57	      }
58	    }
59	    return out;
60	  }
61	
62	  Uri _brouterUri(LatLng a, LatLng b) {
63	    final lonlats =
64	        '${a.longitude.toStringAsFixed(8)},${a.latitude.toStringAsFixed(8)}|'
65	        '${b.longitude.toStringAsFixed(8)},${b.latitude.toStringAsFixed(8)}';
66	    return Uri.https('brouter.de', '/brouter', {
67	      'lonlats': lonlats,
68	      'profile': 'trekking',
69	      'alternativeidx': '0',
70	      'format': 'geojson',
71	    });
72	  }
73	
74	  Uri _osrmRouteUri(LatLng a, LatLng b) {
75	    return Uri.https(
76	      'router.project-osrm.org',
77	      '/route/v1/driving/'
78	          '${a.longitude},${a.latitude};${b.longitude},${b.latitude}',
79	      {'overview': 'full', 'geometries': 'geojson'},
80	    );
81	  }
82	
83	  Future<Object?> _getJson(Uri uri) async {
84	    final client = HttpClient();
85	    try {
86	      client.userAgent = _ua;
87	      client.connectionTimeout = const Duration(seconds: 12);
88	      final req = await client.getUrl(uri);
89	      req.headers.set(HttpHeaders.acceptHeader, 'application/json');
90	      final res = await req.close().timeout(const Duration(seconds: 20));
91	      final body = await utf8.decodeStream(res);
92	      if (res.statusCode < 200 || res.statusCode >= 300) {
93	        throw RoadRouterException('http ${res.statusCode}');
94	      }
95	      return jsonDecode(body);
96	    } finally {
97	      client.close(force: true);
98	    }
99	  }
100	
101	  /// OSRM `/nearest`：距离超过 [snapMaxMeters] 视为失败。
102	  static LatLng? parseOsrmNearest(Object? json, LatLng tap) {
103	    if (json is! Map) return null;
104	    if (json['code'] != 'Ok') return null;
105	    final wps = json['waypoints'];
106	    if (wps is! List || wps.isEmpty) return null;
107	    final wp = wps.first;
108	    if (wp is! Map) return null;
109	    final loc = wp['location'];
110	    if (loc is! List || loc.length < 2) return null;
111	    final lon = (loc[0] as num).toDouble();
112	    final lat = (loc[1] as num).toDouble();
113	    final dist = (wp['distance'] as num?)?.toDouble() ??
114	        _haversineM(tap, LatLng(lat, lon));
115	    if (dist > snapMaxMeters) return null;
116	    return LatLng(lat, lon);
117	  }
118	
119	  static List<LatLng> parseBrouterGeoJson(Object? json) {
120	    if (json is! Map) return const [];
121	    final features = json['features'];
122	    if (features is! List || features.isEmpty) return const [];
123	    final feat = features.first;
124	    if (feat is! Map) return const [];
125	    final geom = feat['geometry'];
126	    if (geom is! Map) return const [];
127	    return _coordsToLatLng(geom['coordinates']);
128	  }
129	
130	  static List<LatLng> parseOsrmRoute(Object? json) {
131	    if (json is! Map) return const [];
132	    if (json['code'] != 'Ok') return const [];
133	    final routes = json['routes'];
134	    if (routes is! List || routes.isEmpty) return const [];
135	    final route = routes.first;
136	    if (route is! Map) return const [];
137	    final geom = route['geometry'];
138	    if (geom is! Map) return const [];
139	    return _coordsToLatLng(geom['coordinates']);
140	  }
141	
142	  static List<LatLng> _coordsToLatLng(Object? raw) {
143	    if (raw is! List) return const [];
144	    final out = <LatLng>[];
145	    for (final c in raw) {
146	      if (c is! List || c.length < 2) continue;
147	      final lon = (c[0] as num).toDouble();
148	      final lat = (c[1] as num).toDouble();
149	      if (out.isNotEmpty) {
150	        final prev = out.last;
151	        if ((prev.latitude - lat).abs() < 1e-8 &&
152	            (prev.longitude - lon).abs() < 1e-8) {
153	          continue;
154	        }
155	      }
156	      out.add(LatLng(lat, lon));
157	    }
158	    return out;
159	  }
160	
161	  static double _haversineM(LatLng a, LatLng b) {
162	    const r = 6371000.0;
163	    final dLat = _rad(b.latitude - a.latitude);
164	    final dLon = _rad(b.longitude - a.longitude);
165	    final x = math.sin(dLat / 2) * math.sin(dLat / 2) +
166	        math.cos(_rad(a.latitude)) *
167	            math.cos(_rad(b.latitude)) *
168	            math.sin(dLon / 2) *
169	            math.sin(dLon / 2);
170	    return 2 * r * math.asin(math.min(1, math.sqrt(x)));
171	  }
172	
173	  static double _rad(double deg) => deg * math.pi / 180;
174	}
175	
176	class RoadRouterException implements Exception {
177	  const RoadRouterException(this.message);
178	  final String message;
179	
180	  @override
181	  String toString() => 'RoadRouterException($message)';
182	}
