138	/// 地图编辑底栏：收起露名称/保存，上拉展开途经点列表。
139	class HelmEditSheet extends StatelessWidget {
140	  const HelmEditSheet({
141	    super.key,
142	    required this.t,
143	    required this.peek,
144	    required this.footer,
145	    required this.onHeaderTap,
146	    required this.onDragDelta,
147	    required this.onDragEnd,
148	    this.list,
149	    this.peekBody = 132,
150	    this.maxHeight,
151	  });
152	
153	  /// 0 收起，1 展开。
154	  final double t;
155	  final Widget peek;
156	  final Widget footer;
157	  final Widget? list;
158	  final VoidCallback onHeaderTap;
159	  final ValueChanged<double> onDragDelta;
160	  final ValueChanged<double> onDragEnd;
161	  final double peekBody;
162	
163	  /// 底栏可用高度；缺省用整屏，地图编辑页应传入 body 高度。
164	  final double? maxHeight;
165	
166	  static double reserve(BuildContext context, {double peekBody = 132}) {
167	    return peekBody + MediaQuery.paddingOf(context).bottom;
168	  }
169	
170	  @override
171	  Widget build(BuildContext context) {
172	    final bottom = MediaQuery.paddingOf(context).bottom;
173	    final bodyH = maxHeight ?? MediaQuery.sizeOf(context).height;
174	    final expanded = t > 0.04;
175	    final peekH = peekBody + bottom * (1 - t);
176	    final sheetH = peekH + (bodyH * 0.52 - peekH) * t;
177	    return SizedBox(
178	      width: double.infinity,
179	      height: sheetH.clamp(peekBody, bodyH * 0.58),
180	      child: Material(
181	        color: AppTheme.card,
182	        elevation: 0,
183	        shadowColor: Colors.transparent,
184	        surfaceTintColor: Colors.transparent,
