187	        child: Column(
188	          children: [
189	            GestureDetector(
190	              behavior: HitTestBehavior.opaque,
191	              onTap: onHeaderTap,
192	              onVerticalDragUpdate: (d) => onDragDelta(d.delta.dy),
193	              onVerticalDragEnd: (d) => onDragEnd(d.primaryVelocity ?? 0),
194	              child: const Padding(
195	                padding: EdgeInsets.only(top: 10, bottom: 8),
196	                child: Center(
197	                  child: SizedBox(
198	                    width: 36,
199	                    height: 4,
200	                    child: DecoratedBox(
201	                      decoration: BoxDecoration(
202	                        color: Color(0xFF5C5C5E),
203	                        borderRadius: BorderRadius.all(Radius.circular(2)),
204	                      ),
205	                    ),
206	                  ),
207	                ),
208	              ),
209	            ),
210	            Padding(
211	              padding: const EdgeInsets.fromLTRB(16, 4, 16, 0),
212	              child: peek,
213	            ),
214	            if (expanded && list != null)
215	              Expanded(child: list!)
216	            else
217	              const SizedBox(height: 8),
218	            Padding(
219	              padding: EdgeInsets.fromLTRB(
220	                16,
221	                4,
222	                16,
223	                expanded ? 12 + bottom : 12 + bottom,
224	              ),
225	              child: footer,
226	            ),
227	          ],
228	        ),
229	      ),
230	    );
231	  }
232	}
