7	
8	/// 手机地图底图：国内高德栅格 + 本地 `z/x/y.png` 缓存。
9	///
10	/// 官方 OSM 在国内经常超时，骑行详情会整片空白。高德是 GCJ-02，
11	/// 展示前用 [toDisplay] 把 GPS/GPX 的 WGS-84 转过去。
12	abstract class HelmOsmTiles {
13	  /// 高德矢量路网（国内 CDN）。
14	  static const urlTemplate =
15	      'https://wprd0{s}.is.autonavi.com/appmaptile?x={x}&y={y}&z={z}&lang=zh_cn&size=1&scl=1&style=7';
16	
17	  static const subdomains = ['1', '2', '3', '4'];
18	
19	  static const referer = 'https://www.amap.com/';
20	
21	  /// [AppCacheStore] 下的子目录名。
22	  static const dirName = 'osm';
23	
24	  static const _ua =
25	      '${AppKeys.appName}/1.0 (${AppKeys.androidPackage}; map tiles)';
26	
27	  /// 底图是火星坐标。
28	  static const usesGcj02 = true;
29	
30	  /// GPS / GPX → 地图显示。
31	  static LatLng toDisplay(LatLng wgs84) =>
32	      usesGcj02 ? ChinaCoord.wgs84ToGcj02(wgs84) : wgs84;
33	
34	  /// 地图点选 → GPS / 路网。
