/// 轨迹速度折线 + 起终点 + 公里标。
List<Widget> rideTrackLayers({
  required List<LatLng> display,
  required GpxSummary? summary,
  required List<LatLng> wgs,
}) {
  if (display.length < 2) return const [];
  final speeds = summary?.pointSpeedsKmh ?? const <double>[];
  final km = GpxUtil.kmMarkers(wgs);
  return [
    PolylineLayer(
      polylines: RideTrackStyle.speedPolylines(
        display,
        speeds,
        fallbackKmh: summary?.avgSpeedKmh,
      ),
    ),
    MarkerLayer(
      markers: [
        for (final m in km)
          Marker(
            point: HelmOsmTiles.toDisplay(m.ll),
            width: 22,
            height: 22,
            child: RideKmBadge(km: m.km),
          ),
        Marker(
          point: display.first,
          width: 26,
          height: 26,
          child: const RideStartGrid(),
        ),
        Marker(
          point: display.last,
          width: 30,
          height: 38,
          alignment: Alignment.bottomCenter,
          child: const RideFinishFlag(),
        ),
      ],
    ),
  ];
