    );
    final center = TransferCenter.to;
    _visible = center.hasWork;
    if (_visible) _slide.value = 1;
    _sub = center.changes.listen((_) => _sync());
  }

  @override
  void dispose() {
    _sub?.cancel();
    _slide.dispose();
    super.dispose();
  }

  /// 任务表变了：跟着切换滑入/滑出，并重画进度。
  void _sync() {
    if (!mounted) return;
